PRAGMA foreign_keys=ON;
CREATE TABLE users (id TEXT PRIMARY KEY, provider TEXT NOT NULL, subject TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', credits INTEGER NOT NULL DEFAULT 0 CHECK(credits>=0), created INTEGER NOT NULL, UNIQUE(provider,subject));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE oauth_states (id TEXT PRIMARY KEY, verifier TEXT NOT NULL, nonce TEXT NOT NULL, provider TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE resumes (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data TEXT NOT NULL, template TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), pack TEXT NOT NULL, credits INTEGER NOT NULL, session_id TEXT UNIQUE, paid INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL);
CREATE TABLE ai_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), input_hash TEXT NOT NULL, cost INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('reserved','completed','failed')), result TEXT, created INTEGER NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 1, expires INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE INDEX ai_requests_owner ON ai_requests(user_id,created);
CREATE INDEX ai_requests_expiry ON ai_requests(status,created);
